content:
Lexical scope
A function can access variables from its own scope and its outer (parent) scopes, but not from inner scopes.

function outer() {
  let x = 10;
  function inner() {
    console.log(x); // works
  }
  inner();
}

closure 
A closure is a function that remembers and can access variables from its outer (lexical) scope even after the outer function has finished executing.

1. Data privacy (encapsulation)
function counter() {
 let count = 0;
 return function () {
   count++;
   return count;
 };
}

const inc = counter();
inc(); // 1
inc(); // 2
//count is hidden from outside.

Pass-by-value vs Pass-by-reference

Pass-by-value = primitives
let a = 5;
change(a);

Pass-by-reference = reference
let user = { name: "Old" };
change(user);

Execution context 
Is a environment in which code is evaluated and executed. 
-----
1. Global Execution Context (GEC) 
let name = "John";
function greet() {
    console.log("Hello");
}
greet();
-----
2. Function Execution Context (FEC) 
function add(a, b) {
    const sum = a + b;
    return sum;
}
add(2, 3);
-----
3. Eval Execution Context 
eval("let x = 10;");

variable shadowing
same variable name inside diffrent scope

let name = "John";
function greet() {
  let name = "Alice"; //shadows the outer variable
}

Block scope = let/ const only var not
code inside curly braces {} such as in if, for, while, or standalone blocks.

let / const
if (true) {
    let a = 5;
}
console.log(a); // ReferenceError
-----
if (true) {
    var x = 10;
}
console.log(x); // 10

Function Scope
var are accessible only inside the function where they are declared

function greet() {
    var message = "Hello";
    console.log(message); // Hello
}
console.log(message); // Error: message is not defined

immutability 
immutability means Primitive types value cannot be changed after it is created
let str = "Hello";
str[0] = "J";
console.log(str); // "Hello"

Currying
technique where a function that takes multiple arguments is transformed into a sequence of functions 
One argument at a time.
function add(a) {
  return function (b) {
    return a + b;
  };
}
console.log(add(2)(3)); // 5

Partial application
technique where a function that takes multiple arguments is transformed into a sequence of functions 
Fill in some arguments now, the rest later.
function multiply(a, b) {
  return a * b;
}
function partialMultiply(a) {
  return function (b) {
    return multiply(a, b);
  };
}
const double = partialMultiply(2);
console.log(double(5)); // 10

Higher-order functions
Take function arguments and return function arguments
function greet(name) {
  return `Hello, ${name}!`;
}
function processUser(callback) {
  return callback("Alice");
}
console.log(processUser(greet));

First-class functions
functions are treated like any other value.
1 Assigned to variables
2 Passed as arguments to other functions
3 Returned from other functions
4 Stored in arrays or objects
const numbers = [1, 2, 3, 4];
const squares = numbers.map(function(num) {
  return num * num;
});
console.log(squares); // [1, 4, 9, 16]

Pure Function vs Impure Function

Pure Function
1 Always returns the same result for the same arguments. 
2 not modify external variables
function add(a, b) {
  return a + b;
}
-----
Impure Function
function getCurrentTime() {
  return Date.now();
}

let count = 0;
function increment() {
  count++;
}

Function composition
combining two or more functions into a new function 
const double = x => x * 2;
const addOne = x => x + 1;
const composed = x => double(addOne(x));

Function declaration vs Function expression

Function declaration = function keyword
hello(); // Works
function hello() {
  console.log("Hello");
}
-----
Function expression = const / let
hello(); // ReferenceError
const hello = function () {
  console.log("Hello");
};

Arrow functions / Regular functions.

Regular Function  
1. Regular function as a constructor 
2. It have own THIS
3. Object methods, constructors, event handlers

function Person() {
  this.name = "John";
  this.greet = () => {
    console.log(this.name);
  };
}
let personx = new Person();
personx.greet(); // John
-----
Arrow functions
1. No constructor 
2. No This
3. Callbacks, array methods, closures

const person = {
  name: "John",
  greet() {
    console.log(this.name);
  }
};
person.greet(); // John

call() / apply() / bind() / JavaScript method that

call() = invokes a function immediately with a specified this value and arguments passed individually. 
const person = {
    name: "Alice"
};
function greet(city, country) {
    console.log(`Hello, I'm ${this.name} from ${city}, ${country}`);
}
greet.call(person, "London", "UK");
-----
apply() = invokes a function immediately with a specified this value and arguments passed in array
greet.apply(person, ["Paris", "France"]);
-----
bind() = not execute immediately it returns a new function with the specified this value. 
const person = {
    name: "Charlie"
};
function greet(city) {
    console.log(`Hello, I'm ${this.name} from ${city}`);
}
const greetCharlie = greet.bind(person);
greetCharlie("New York");

Recursion vs  Tail recursion vs Non Trail
Recursion = function calls itself to solve a problem by breaking it into smaller subproblems. 
function countSteps(step) {
  if (step === 0) {
    console.log("Reached the ground.");
    return;
  }
  countSteps(step - 1);
}
countSteps(5);
-----
Tail recursion = Recursive call is the last operation
function totalMoney(bills, index = 0, total = 0) {
  if (index === bills.length) {
    return total;
  }
  return totalMoney(bills, index + 1, total + bills[index]);
}
const bills = [100, 200, 50, 500];
console.log(totalMoney(bills)); // 850
-----
Non Trail
function totalMoney(bills, index = 0) {
  if (index === bills.length) {
    return 0;
  }
  return bills[index] + totalMoney(bills, index + 1);
}

Rest parameter vs Default parameter

Rest parameter = indefinite number of arguments as array / Spread syntax ...
function functionName(...args) {
    // args is an array
}
-----
Default parameter = Default value is provided
function greet(name = "Guest") {
    console.log("Hello, " + name);
}

Template literals.
backticks ` `
let name = "Alice";
let age = 25;
console.log(`My name is ${name} and I am ${age} years old.`);

Destructuring assignment.
const numbers = [10, 20, 30];
const [a, b, c] = numbers;

Spread operator
( … ) expand an iterable
const arr1 = [1, 2, 3];
const arr2 = [...arr1];

Rest Operator (...) 
function sum(...numbers) {
  return numbers.reduce((total, num) => total + num, 0);
}
-----
const [first, second, ...remaining] = fruits;
-----
const { name, ...details } = student;

Optional chaining - ES11
access nested object properties or call methods without throwing an error if an intermediate value is null or undefined. 
const user = {};
const city = user.address?.city ?? "Unknown";

Symbol is a unique and immutable primitive value used as an object property key
const id = Symbol("id");
const user = {
    name: "John",
    [id]: 101
};
console.log(id);       // null
console.log(user[id]);       // 101

Iterator is an object that allows sequential access to elements of a collection.  by next() 
let str = "abc";
let it = str[Symbol.iterator]();
console.log(it.next()); //{value: "a", done: false}

Generator is a special function that can pause and resume execution. 
function* + yield
function* numbers() {
    yield 1;
    yield 2;
    yield 3;
}
const gen = numbers();
console.log(gen.next());// { value: 1, done: false }
console.log(gen.next());

Map()
stores key-value pairs where keys can be of any type. 
set(), get(), has(), delete(), clear()

const map = new Map();
map.set("name", "John");
console.log(map.get("name")); //John
map.delete("age");
for (let [key, value] of map) {
  console.log(key, value);
}

Set()
stores unique values only.
const numbers = new Set();
numbers.add(10);
for (let value of numbers) {
    console.log(value);
}

WeakMap()
1 Keys must be objects. 
2 not iterable. 
3 no size property 

let user = {
    name: "John"
};
const weakMap = new WeakMap();
weakMap.set(user, "Admin");

WeakSet()
1 store only objects 
2 not iterable. 
3 no size property 

let obj = {
    id: 1
};
const weakSet = new WeakSet();
weakSet.add(obj);

Dynamic imports
load a module at runtime 

import('./module.js')
.then(module => {
    module.myFunction();
})
.catch(error => {
    console.error(error);
});

ES modules
module system let you split code into multiple files and share variables, functions, and classes using export and import. 

1 import / export
2 Tree Shaking
3 Asynchronous loading

export const PI = 3.14;

export function add(a, b) {
  return a + b;
}

CommonJS (CJS)
1 require() / module.exports
2 Synchronous Loading

function add(a, b) {
  return a + b;
}
module.exports = add;
----------------------------------------
// app.js
const add = require('./math');

Top-level await.
Call await on root not inside async function
const response = await fetch("https://api.example.com/users");

Optional catch binding (ES2019) 
catch does not have error argument
try {
} catch {
  console.log("An error occurred.");
}

Promise.finally (ES9)
After a Promise settles 
Use = cleanup / loading animation

fetchData()
  .then(data => {
    console.log("Success:", data);
  })
  .catch(err => {
    console.log("Error:", err);
  })
  .finally(() => {
    console.log("Operation completed.");
  });

Callbacks
callback is a function that is passed as an argument to another function and is executed later, 
function greet(name, callback) {
    callback();
}
function sayBye() {
    console.log("Goodbye!");
}
greet("Alice", sayBye);

Callback Hell / Pyramid of Doom

loginUser(function(user) {
    getProfile(user, function(profile) {
        getOrders(profile, function(orders) {
            console.log(orders);
        });
    });
});

Sequential vs Parallel execution

Sequential = one after another 
const user = await getUser();
const orders = await getOrders(user.id);
---
Parallel = multiple asynchronous tasks are started together and can make progress simultaneously 
const [users, products, orders] = await Promise.all([
  fetchUsers(),
  fetchProducts(),
  fetchOrders()
]);

Event Emitter 
a pattern (and a built-in class in Node.js) that allows objects to emit named events and other parts of your code to listen and react to them.
publish-subscribe (pub/sub) pattern. 

const EventEmitter = require("events");
const emitter = new EventEmitter();
emitter.on("message", (text) => {
  console.log("Received:", text);
});
emitter.emit("message", "Hello World");

Web Workers
Web Workers let you run JavaScript in a background thread, separate from the main UI thread. 

SharedArrayBuffer = special memory buffer (main thread + workers)

onmessage = function(e) {
  const result = heavyComputation(e.data);
  postMessage(result);
};

const worker = new Worker("worker.js");
worker.postMessage(data);
worker.onmessage = (e) => {
  console.log("Result:", e.data);
};

Asynchronous iterables
return Promises instead of immediate values.

const stream = fs.createReadStream("file.txt", { encoding: "utf8" });
for await (const chunk of stream) {
console.log(chunk);
}

Prototype
Every constructor function has a prototype object.
function Person(name) {
  this.name = name;
}
Person.prototype.sayHello = function () {
  console.log(`Hi, I'm ${this.name}`);
};
const user = new Person("Alex");
user.sayHello(); // Hi, I'm Alex

__proto__ 
property of Object internal link = that refers to an object's prototype. It is part of JavaScript's prototype inheritance mechanism.

function Person(name) {
  this.name = name;
}
const p1 = new Person("Amit");
console.log(p1.__proto__ === Person.prototype); // true

prototype = “What I give to my children”
proto = “Who my parent is”

ES6 classes
1 look like traditional OOP classes
2 JavaScript’s prototype-based inheritance system.
Strict mode
Inheritance = extends and super

class Person {
  constructor(name) {
    this.name = name;
  }
  greet() {
    console.log("Hello " + this.name);
  }
}
---
function Person(name) {
  this.name = name;
}
Person.prototype.greet = function () {
  console.log("Hello " + this.name);
};

(#class) Method overriding 
Method overriding happens when a child class provides its own implementation of a method that already exists in its parent class. 

class Animal {
  speak() {
    console.log("Animal makes a sound");
  }
}

class Dog extends Animal {
  speak() {
    super.speak(); // call parent method
    console.log("Dog barks");
  }
}

const d = new Dog();
d.speak();

(#class) Method borrowing
using a method from one class on an instance of another class, without copying the method.
call() / apply()

class Person {
  constructor(name) {
    this.name = name;
  }
  greet() {
    return `Hello, I'm ${this.name}`;
  }
}

class Animal {
  constructor(name) {
    this.name = name;
  }
}

const p = new Person("Asha");
const a = new Animal("Doggo");

console.log(p.greet.call(a)); // Borrow greet() from Person and use it for Animal

Own vs Inherited properties

const animal = {
  eats: true
};
const dog = Object.create(animal);
dog.name = "Buddy";
console.log(dog.hasOwnProperty("name")); // true
console.log(dog.hasOwnProperty("eats")); // false

instanceof
instanceof operator in JavaScript checks whether an object is an instance of a particular constructor or class by looking at its prototype chain. 
class Person {}
const p = new Person();
console.log(p instanceof Person); // true
console.log(p instanceof Object); // true

Constructor function
regular function used with the new keyword. 
Hoisting 
Inheritance  = Manual prototype chaining

function Person(name, age) {
  this.name = name;
  this.age = age;
}

Person.prototype.greet = function() {
  console.log(`Hello, I'm ${this.name}`);
};
const john = new Person("John", 25);
john.greet();

Object.create() 
creates a new object using another object as its prototype. It's commonly used for inheritance without using classes. 
const person = {
  greet() {
    console.log("Hello!");
  }
};
const john = Object.create(person);
john.greet(); // Hello!

Private class fields (ES11)
class properties that cannot be accessed or modified outside the class
class Person {
  #name; // private field
  constructor(name) {
    this.#name = name;
  }
  getName() {
    return this.#name;
  }
}

Prototype chain
mechanism that allows objects to inherit properties and methods from other objects. 

const animal = {
  eats: true,
  walk() {
    console.log("Animal walks");
  }
};
const dog = {
  barks: true
};
dog.__proto__ = animal; // sets prototype
console.log(dog.barks); // true (own property)
console.log(dog.eats);  // true (from prototype: animal)
dog.walk();             // "Animal walks"

Object literals
curly braces {} with key-value pairs
person.name = dot notation 
person["age"] = bracket notation

const person = {
  name: "Alice",
  age: 25,
  isStudent: false
};

Computed property names
const key = "name";
const person = {
  [key]: "Alice"
};
console.log(person); // { name: "Alice" }

(#class) Getters and setters
Getters = read a property. 
Setters = assign a value to a property.

class Person {
  constructor(firstName, lastName) {
    this.firstName = firstName;
    this.lastName = lastName;
  }

  get fullName() {
    return `${this.firstName} ${this.lastName}`;
  }

  set fullName(value) {
    const parts = value.split(" ");
    this.firstName = parts[0];
    this.lastName = parts[1];
  }
}

const person = new Person("John", "Doe");
console.log(person.fullName); // Getter Use
person.fullName = "Jane Smith"; // Setters Use
console.log(person.firstName); // Jane
console.log(person.lastName);  // Smith

Property descriptors
characteristics (attributes) of an object's property

Object.getOwnPropertyDescriptor()
Object.defineProperty()
Object.defineProperties()

const person = {};
Object.defineProperty(person, "name", {
  value: "Alice",
  writable: false,
  enumerable: true, // looping 
  configurable: false
});

WeakRef
caching without preventing garbage collection
memory-sensitive data structures

let obj = { data: 123 };
let ref = new WeakRef(obj);
ref.deref();

Debounce vs Throttle

Debounce = Delays function execution until user stops triggering events
Throttle = Limits how often a function can execute

Debounce

Runs after the event stops for a specified time.

function debounce(fn, delay) {
  let timer;

  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const search = debounce((value) => {
  console.log("API call:", value);
}, 500);

search("r");
search("re");
search("rea");
search("react"); // Only this runs after 500ms
-----

Throttle

Runs at most once during a specified time interval.

function throttle(fn, delay) {
  let last = 0;

  return (...args) => {
    const now = Date.now();

    if (now - last >= delay) {
      last = now;
      fn(...args);
    }
  };
}

const scrollHandler = throttle(() => {
  console.log("scroll");
}, 500);

window.addEventListener("scroll", scrollHandler);

Referential equality
comparing whether two variables point to the same object or array in memory, rather than whether they contain the same values.

const obj1 = { name: "Alice" };
const obj2 = { name: "Alice" };
const obj3 = obj1;
console.log(obj1 === obj2); // false
console.log(obj1 === obj3); // true

1. Encapsulation
binds data and methods into a single class

Benefits
1 Protects data
2 Prevents accidental modification
3 Makes code easier to maintain

class BankAccount {
  #balance = 0; // Private field

  deposit(amount) {
    this.#balance += amount;
  }

  getBalance() {
    return this.#balance;
  }
}

const account = new BankAccount();
account.deposit(1000);
console.log(account.getBalance()); // 1000
// console.log(account.#balance); // ❌ Error (private)

2. Inheritance
Inheritance allows one class to reuse properties and methods of another class.

class Animal {
  speak() {
    console.log("Animal makes sound");
  }
}

class Dog extends Animal {
  bark() {
    console.log("Dog barks");
  }
}

const dog = new Dog();
dog.speak(); // inherited
dog.bark();

3. Polymorphism
Polymorphism means one interface, many implementations.


class Animal {
  speak() {
    console.log("Animal sound");
  }
}

class Dog extends Animal {
  speak() {
    console.log("Bark");
  }
}

class Cat extends Animal {
  speak() {
    console.log("Meow");
  }
}

const animals = [
  new Dog(),
  new Cat()
];

animals.forEach(animal => animal.speak());

4. Abstraction
hiding internal implementation details and showing only essential functionality to the user.

class Shape {
  area() {
    throw new Error("Method must be implemented");
  }
}

class Circle extends Shape {
  constructor(radius) {
    super();
    this.radius = radius;
  }

  area() {
    return Math.PI * this.radius * this.radius;
  }
}

const circle = new Circle(5);
console.log(circle.area());

support multiple inheritance = no
A class can extend only one class

IIFE (Immediately Invoked Function Expression)
a function that is defined and executed immediately after it is created.

(function () {
    console.log("Hello");
})();
